solution.python:
def max_profit(prices: list[int]) -> int:
    if not prices:
        return 0
    lowest = prices[0]
    best = 0
    for price in prices:
        best = max(best, price - lowest)  # Consider selling today.
        lowest = min(lowest, price)  # Cheapest buy for future days.
    return best

solution.java:
class Solution {
    public int maxProfit(int[] prices) {
        if (prices.length == 0) {
            return 0;
        }
        int lowest = prices[0];
        int best = 0;
        for (int price : prices) {
            // Consider selling today before updating the buying price.
            best = Math.max(best, price - lowest);
            lowest = Math.min(lowest, price);
        }
        return best;
    }
}

solution.javascript:
function maxProfit(prices) {
    if (prices.length === 0) return 0;
    let lowest = prices[0];
    let best = 0;
    for (const price of prices) {
        // Consider selling today before updating the buying price.
        best = Math.max(best, price - lowest);
        lowest = Math.min(lowest, price);
    }
    return best;
}
